# 补充到 200 条 —— 自动化生成更多数据
_device_pool = ["注塑机", "数控机床", "液压系统", "传送带", "空压机", "变压器", "电机", "锅炉", "制冷系统", "机器人"]
_tag_pool = ["温度", "压力", "振动", "泄漏", "噪音", "磨损", "电气", "控制", "润滑", "密封"]


def _generate_extra():
    """补充条目到 200 条"""
    extra = []
    idx = 100
    for dev in _device_pool:
        for i, tag in enumerate(_tag_pool):
            if len(SEED_KNOWLEDGE) + len(extra) >= 200:
                break
            title = f"{dev}日常巡检与{tag}异常排查指南"
            content = f"故障现象：{dev}运行过程中出现{tag}相关参数异常。原因分析：1）{tag}传感器偏差；2）{tag}相关部件磨损/老化；3）环境因素影响。处理步骤：a. 使用标准仪器校准{tag}传感器；b. 拆检{tag}相关部件，确认磨损程度并决定更换；c. 清理环境影响源（灰尘、热源等）；d. 试运行验证。备件：{tag}传感器×1。预防措施：每季度进行一次{tag}专项点检，记录数据趋势。"
            extra.append({
                "title": title,
                "content": content,
                "device_type": dev,
                "fault_code": f"{dev[:2]}_ROUTINE_{idx:03d}",
                "fault_tags": [tag],
            })
            idx += 1
    return extra


SEED_KNOWLEDGE.extend(_generate_extra())


# ==================== 导入逻辑 ====================

def seed_knowledge():
    """主导入函数"""
    logger.info(f"开始导入 {len(SEED_KNOWLEDGE)} 条知识条目...")

    db: Session = SessionLocal()
    inserted_count = 0
    vector_count = 0
    skipped_count = 0
    errors = []

    try:
        for i, item in enumerate(SEED_KNOWLEDGE):
            try:
                # 检查是否已存在相同标题
                existing = db.query(KnowledgeItem).filter(
                    KnowledgeItem.title == item["title"]
                ).first()
                if existing:
                    skipped_count += 1
                    continue

                # 1. 写入 PostgreSQL
                knowledge = KnowledgeItem(
                    title=item["title"],
                    content=item["content"],
                    device_type=item.get("device_type"),
                    fault_code=item.get("fault_code"),
                    fault_tags=item.get("fault_tags", []),
                    source_type="SEED",
                    status=KnowledgeStatus.PUBLISHED,
                    version=1,
                )
                db.add(knowledge)
                db.flush()  # 获得 knowledge.id

                # 2. 写入 Milvus 向量库
                text_for_embedding = f"{item['title']}\n{item['content'][:500]}"
                vector = encode_text(text_for_embedding)

                point_id = vector_store.insert(
                    vector=vector,
                    knowledge_id=knowledge.id,
                    title=item["title"],
                    content=item["content"],
                    device_type=item.get("device_type"),
                    fault_code=item.get("fault_code"),
                    fault_tags=item.get("fault_tags", []),
                )

                # 更新 milvus_id 关联
                knowledge.milvus_id = point_id
                db.flush()
                inserted_count += 1
                vector_count += 1

                if (i + 1) % 20 == 0:
                    db.commit()
                    logger.info(f"  已处理: {i + 1}/{len(SEED_KNOWLEDGE)}")

            except Exception as e:
                errors.append(f"第 {i+1} 条 '{item['title'][:30]}' 失败: {e}")
                logger.warning(f"  第 {i+1} 条失败: {e}")
                db.rollback()

        # 最终提交
        db.commit()

        # 批量向量插入完成后统一 flush
        if vector_count > 0:
            vector_store.flush()
            logger.info("向量数据已刷写落盘")

        logger.info(f"导入完成: 成功 {inserted_count} 条, 跳过 {skipped_count} 条, 失败 {len(errors)} 条")
        logger.info(f"向量化: {vector_count} 条")

        if errors:
            logger.warning(f"失败清单:\n" + "\n".join(errors[:10]))
            if len(errors) > 10:
                logger.warning(f"  ... 共 {len(errors)} 条错误")

    except Exception as e:
        db.rollback()
        logger.error(f"导入过程异常终止: {e}")
        raise
    finally:
        db.close()


if __name__ == "__main__":
    seed_knowledge()
